 * @modifier -readonly — Read-only state.
 * @modifier -required — Show the required-field asterisk next to the label.
 * @modifier -variant-toggle — Render as a switch instead of a box.
 * @modifier -size-sm — Small.
 * @modifier -size-lg — Large.
 * @part .asterisk — The required-field asterisk.
 * @pseudo ::before — The masked tick or dash glyph centered in the box; on `-variant-toggle` it becomes the sliding handle instead.
 * @pseudo ::after — On `-variant-toggle`, the state glyph riding the handle: an X when off, a check when on.
 * @cssproperty --pantoken-cb-glyph <url> — The box's mask glyph: a tick when checked, a dash when indeterminate.
 * @cssproperty --pantoken-toggle-h <length> — The toggle switch height.
 * @cssproperty --pantoken-toggle-w <length> — The toggle track width.
 * @cssproperty --pantoken-toggle-bw <length> — The toggle border width.
 * @cssproperty --pantoken-toggle-inset <length> — The handle inset from each track edge.
 * @cssproperty --pantoken-toggle-handle <length> — The computed handle diameter.
 * @cssstate checked
 * @cssstate indeterminate
 * @cssstate disabled
 * @accessibility A native `<input type="checkbox">` drives `:checked`, `:indeterminate`, and `:disabled`; set `el.indeterminate = true` in JavaScript for the mixed state, and note that `-readonly` is styling only since checkboxes have no native readonly attribute.
 * @example
 * ```html
 * <label class="pfx-checkbox --display-block --mb-sm">
 *   <input type="checkbox" checked>Checkbox
 * </label>
 * <label class="pfx-checkbox -variant-toggle">
 *   <input type="checkbox">Toggle
 * </label>
 * ```
 * @related radio — The single-select counterpart.
 */
.pfx-checkbox {
  display: inline-flex;
  align-items: center;
  gap: var(--instui-component-checkbox-gap);
  color: var(--instui-component-checkbox-label-base-color);
  font-family: var(--instui-component-checkbox-font-family);
  font-size: var(--instui-component-checkbox-font-size-md);
  font-weight: var(--instui-component-checkbox-font-weight);
  line-height: var(--instui-component-checkbox-line-height);
}

/* labelPlacement: the control comes first in the markup, so reorder with flex. Default is "end"
   (label after the control); "start" puts it before, "top" stacks it above. */
.pfx-checkbox.-label-placement-end {
  flex-direction: row;
}

.pfx-checkbox.-label-placement-start {
  flex-direction: row-reverse;
}

.pfx-checkbox.-label-placement-top {
  flex-direction: column-reverse;
  align-items: flex-start;
}

/* Base control: a native checkbox restyled via appearance:none so the InstUI border/background/checked
   tokens all apply, with the tick masked into a ::before. Scoped away from the --toggle switch. */
.pfx-checkbox:not(.pfx-checkbox.-variant-toggle) input[type="checkbox"] {
  --pantoken-cb-glyph: var(--instui-icon-check) center / contain no-repeat;
  appearance: none;
  -webkit-appearance: none;
  display: inline-grid;

/**
 * @component table.cell
 * @memberOf table
 * @selector td
 * @summary A data cell (InstUI `Table.Cell`).
 * @remarks The parent `table`'s `-layout-stacked` modifier stacks this member as a block and labels it via `::before` — see `table`'s own doc for that modifier.
 * @structure
 * @component table {
 *   tbody {
 *     tr {
 *       td {}
 *     }
 *   }
 * }
 */
.pfx-table td {
  color: var(--instui-component-table-cell-color);
  line-height: var(--instui-component-table-cell-line-height);
  padding: var(--instui-component-table-cell-padding-vertical)
    var(--instui-component-table-cell-padding-horizontal);
}

/* No border of its own — the separator lives on the row (see table.row). Reset with tbody specificity
 (0,1,2) so a host stylesheet's cell borders (e.g. `.pantoken-prose td`, 0,1,1) can't leak in. */
.pfx-table tbody td {
  border: 0;
}

/* layout="stacked": stack as a block, labelled by its column via ::before (pure CSS can't pull the
 <th> text automatically, so the author supplies a `data-label` per cell). */
.pfx-table.-layout-stacked td {
  display: block;
  width: auto;
}

.pfx-table.-layout-stacked tbody td[data-label]::before {
  content: attr(data-label);
  display: block;
  font-weight: var(--instui-component-table-head-font-weight);
  color: var(--instui-component-table-col-header-color);
}

