 */
@scope (.pfx-simple-select) {
  @supports (appearance: base-select) {
    & {
      appearance: base-select;
    }

    /* Keep simple-select's own background-image caret; hide the UA-generated picker icon. */
    &::picker-icon {
      display: none;
    }

    &::picker(select) {
      border: var(--instui-component-select-popover-border-width) solid
        var(--instui-component-text-input-border-color);
      border-radius: var(--instui-border-radius-lg);
      box-shadow: var(--instui-elevation-topmost);
      background-color: var(--instui-component-options-item-background);
      padding: 0;
      margin: 0;
      overflow: hidden;
      appearance: base-select;
    }

    & option {
      padding: var(--instui-component-options-item-padding-vertical)
        var(--instui-component-options-item-padding-horizontal);
      background-color: var(--instui-component-options-item-background);
      color: var(--instui-component-options-item-color);
      font-family: var(--instui-component-options-item-font-family);
      font-weight: var(--instui-component-options-item-font-weight);
      font-size: var(--instui-component-options-item-font-size);
      line-height: var(--instui-component-options-item-line-height);
      cursor: pointer;
    }

