      for (const dependency of pkg.workspaceDeps) visit(dependency);
    };
    for (const name of ["@pantoken/components", "@pantoken/css", "@pantoken/interactions"])
      visit(name);
    const packs = join(out, "packs");
    mkdirSync(packs, { recursive: true });

